use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();let digest=hash(p);if let Some(old)=pins.insert(p.to_str().unwrap().into(),digest.clone()){assert_eq!(old,digest);}}
fn save(p:impl AsRef<Path>,v:Value){fs::write(p,format!("{}\n",serde_json::to_string_pretty(&v).unwrap())).unwrap()}
fn main(){let root=Path::new("/tmp/zopro-outlined-snapshot-fence");let parent=Path::new("/tmp/zopro-front-snapshot-fence");let mode=std::env::args().nth(1).unwrap();if mode=="finalize"{assert_eq!(read(root.join("preflight/result.json"))["status"],"complete");assert_eq!(read(root.join("preflight-validation.json"))["status"],"passed");let mut config=read(root.join("perf-template.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(read(root.join("input-pins.json"))).unwrap();let mut prior:BTreeSet<String>=serde_json::from_value(config["prior_proof_sha256"].clone()).unwrap();let inventory=read(root.join("preflight-proof-inventory.json"));assert_eq!(inventory.as_object().unwrap().len(),36);for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);if p.ends_with(".proof"){assert!(prior.insert(h.as_str().unwrap().into()));}}for name in ["input-pins.json","preflight-plan.json","preflight-proof-inventory.json","preflight-validation.json","preflight/result.json"]{add(root.join(name),&mut pins);}config["pins"]=json!(pins);config["prior_proof_sha256"]=json!(prior);save(root.join("perf-plan.json"),config);println!("PERF_FINALIZED4variants{}pins{}prior",pins.len(),prior.len());return;}
assert_eq!(mode,"prepare");assert_eq!(read(root.join("native/result.json"))["status"],"complete");assert_eq!(read(root.join("codegen-gate.json"))["performance_may_proceed"],true);assert_eq!(read(root.join("outline-audit.json"))["status"],"passed");
let old=read(parent.join("perf-plan.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(old["pins"].clone()).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h,"old control/input changed {p}");}for(p,h)in read(root.join("build-input-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if let Some(old)=pins.insert(p.clone(),h.as_str().unwrap().into()){assert_eq!(old,h.as_str().unwrap());}}
for name in ["experiment.json","prepare.rs","prepare.json","native-plan.json","outline-audit.json","parent-source-pins.json","source-audit.rs","source-audit.json","protocol.rs","analyze.rs","analyze","analyze-tests","analyze-tests.log","codegen-gate.rs","codegen-gate.json","codegen.txt","inventory-preflight.sh","validate-preflight.jq","build-input-pins.json","ordering-review.md"]{add(root.join(name),&mut pins);}
let artifact=read(root.join("native/candidate/artifacts.json"));assert_eq!(hash(artifact["binary"].as_str().unwrap()),artifact["binary_sha256"].as_str().unwrap());add(root.join("native/candidate/artifacts.json"),&mut pins);add(artifact["binary"].as_str().unwrap(),&mut pins);for(p,h)in artifact["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}
let log=root.join("native/libraries/stdout.log");let mut scheduler=BTreeMap::new();for line in fs::read_to_string(&log).unwrap().lines(){if let Ok(v)=serde_json::from_str::<Value>(line){if v["reason"]=="compiler-artifact"{if let Some(name)=v["target"]["name"].as_str(){if ["crossbeam_deque","crossbeam_epoch","crossbeam_utils","rayon_core"].contains(&name){for f in v["filenames"].as_array().unwrap(){let p=f.as_str().unwrap();if p.ends_with(".rlib"){assert!(scheduler.insert(name.to_owned(),p.to_owned()).is_none());add(p,&mut pins);}}}}}}}assert_eq!(scheduler.len(),4);save(root.join("linked-scheduler-libraries.json"),json!(scheduler));add(root.join("linked-scheduler-libraries.json"),&mut pins);add(&log,&mut pins);
let mut template=read(parent.join("all-nine-template.json"));let mut prior:BTreeSet<String>=serde_json::from_value(template["prior_proof_sha256"].clone()).unwrap();for(p,h)in read(parent.join("proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert!(prior.insert(h.as_str().unwrap().into()));}}assert_eq!(prior.len(),3774);
let variants=json!([{"name":"accepted","binary":"/tmp/zopro-grouping-module/native/candidate-sdk"},{"name":"off","binary":root.join("native/candidate-sdk"),"environment":{"ZOPRO_CPU_FRONT_SNAPSHOT_FENCE":"0"}},{"name":"on","binary":root.join("native/candidate-sdk"),"environment":{"ZOPRO_CPU_FRONT_SNAPSHOT_FENCE":"1"}},{"name":"inlined","binary":"/tmp/zopro-front-snapshot-fence/native/candidate-sdk","environment":{"ZOPRO_CPU_FRONT_SNAPSHOT_FENCE":"1"}}]);template["variants"]=variants.clone();template["prior_proof_sha256"]=json!(prior);save(root.join("all-nine-template.json"),template.clone());add(root.join("all-nine-template.json"),&mut pins);
let mut steps=Vec::new();for mode in ["off","on"]{for case in template["cases"].as_array().unwrap(){let shape=case["shape"].as_str().unwrap();let image=case["image"].as_str().unwrap();let stem=Path::new(image).file_stem().unwrap().to_str().unwrap();let name=format!("{mode}-w4-{shape}");let proof=root.join("preflight-proofs").join(&name);steps.push(json!({"kind":"command","name":format!("{name}-prove"),"argv":[root.join("native/candidate-sdk"),image.into(),case["request"].clone(),json!("1"),json!(proof.join(stem))],"environment":{"RAYON_NUM_THREADS":"4","ZOPRO_CPU_FRONT_SNAPSHOT_FENCE":if mode=="on"{"1"}else{"0"}},"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("{name}-verify"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",proof.to_str().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":600}));}}
let check=json!(["jq","-n","--slurpfile","inventory",root.join("preflight-proof-inventory.json"),"--slurpfile","template",root.join("all-nine-template.json"),"-f",root.join("validate-preflight.jq")]);steps.push(json!({"kind":"command","name":"proof-inventory","argv":["bash",root.join("inventory-preflight.sh")],"timeout_seconds":30}));steps.push(json!({"kind":"command","name":"validate-inventory","argv":check,"timeout_seconds":30}));assert_eq!(steps.len(),38);
let mut perf=read(parent.join("perf-template.json"));perf["variants"]=variants;perf["prior_proof_sha256"]=json!(prior);perf["pins"]=json!({});perf["checks"]=json!([check]);assert_eq!(perf["cases"].as_array().unwrap().len(),10);assert_eq!(perf["blocks"],7);let sdk=perf["cases"].as_array().unwrap().iter().map(|c|c["rounds"].as_u64().unwrap()+3).sum::<u64>()*7*4;assert_eq!(sdk,11480);save(root.join("perf-template.json"),perf.clone());add(root.join("perf-template.json"),&mut pins);save(root.join("input-pins.json"),json!(pins));save(root.join("preflight-plan.json"),json!({"version":1,"source_pins":root.join("input-pins.json"),"environment":perf["environment"],"steps":steps}));println!("FROZEN4variants11480latencySDK680profileSDK18preflightproofs{}pins{}prior",pins.len(),prior.len());}
